    @Test
    void 重试_失败样本累加_原失败样本不扣回_同尝试重复回执不重计() throws Exception {
        long releaseId = setupFailedFirstAttempt("m1", 100);
        long t1 = jdbc.queryForObject("SELECT id FROM rollout_task WHERE attempt_no = 1", Long.class);
