        // 场景一：PAUSED 发布单不能重试
        long pausedRelease = setupFailedFirstAttempt("mp", 1);
        long pt1 = jdbc.queryForObject("SELECT id FROM rollout_task WHERE release_id = ? AND attempt_no = 1",
