209	        if ((long) order.roundFailed() * 100 < (long) samples * order.failureThresholdPercent()) {
210	            return;
211	        }
212	        if (releaseRepository.pauseIfActive(order.id()) == 1) {
213	            pauseRecordRepository.insert(order.id(), order.monitorRound(), triggerTaskId,
214	                    order.roundSuccess(), order.roundFailed(), Instant.now(clock).toString());
