        KeyHolder keyHolder = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO rollout_task (release_id, device_id, status, attempt_no, prev_task_id)"
                            + " VALUES (?, ?, 'PENDING', 1, NULL)",
                    new String[]{"id"});
